import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const _=JSON.parse('{"title":"2002年 · 杠杆的双刃","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2002年.md","filePath":"05_quotes/by-year/2002年.md"}'),r={name:"05_quotes/by-year/2002年.md"};function u(c,e,q,s,b,h){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2002年-·-杠杆的双刃" tabindex="-1">2002年 · 杠杆的双刃 <a class="header-anchor" href="#_2002年-·-杠杆的双刃" aria-label="Permalink to &quot;2002年 · 杠杆的双刃&quot;">​</a></h1><blockquote><p>衍生品是大规模杀伤性金融武器，其危险虽然目前潜伏，但可能是致命的。——巴菲特（72岁）</p></blockquote><p>本页收录2002年致股东信中的经典语录。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>衍生品是大规模杀伤性金融武器，其危险虽然目前潜伏，但可能是致命的。</p></blockquote><blockquote><p>在银行业，认识到&quot;关联&quot;问题是建立联邦储备系统的原因之一。在美联储成立之前，弱银行的倒闭有时会对先前强健的银行造成突然和意外的流动性需求，导致它们也相继倒闭。</p></blockquote><blockquote><p>许多 CEO 近年来在办公室行为不端，伪造数字，因平庸的商业成就而领取荒唐的薪酬。这些原本正派的人只是追随了梅·韦斯特的职业道路：&quot;我曾是白雪公主，但我迷失了方向。&quot;</p></blockquote><blockquote><p>董事不应该在薪酬委员会任职，除非他们自己能够代表所有者进行协商。他们应该解释他们对薪酬的看法以及如何衡量业绩。此外，在处理股东资金时，他们应该表现得就像是在处理自己的资金。</p></blockquote><blockquote><p>在1890年代，塞缪尔·冈珀斯将有组织劳工的目标描述为&quot;更多！&quot;在1990年代，美国的CEO采用了他的战斗口号。</p></blockquote><blockquote><p>如果一家公司仍未将期权费用化，或其养老金假设是幻想的，要小心。当管理层在可见方面走低路时，他们在幕后很可能遵循类似的路径。厨房里很少只有一只蟑螂。</p></blockquote><blockquote><p>吹捧EBITDA是一种特别有害的做法。这样做暗示折旧不是真正的费用，因为它是&quot;非现金&quot;费用。实际上，折旧是一种特别没有吸引力的费用，因为它代表的现金支出是预先支付的，在所获得的资产为业务提供任何利益之前。</p></blockquote><blockquote><p>难以理解的脚注通常表明管理层不可信。如果您无法理解脚注或其他管理层解释，通常是因为CEO不想让您理解。</p></blockquote><blockquote><p>我希望我现在不知道我当时不知道的事情。</p></blockquote><blockquote><p>廉价的再保险是愚蠢的交易。</p></blockquote><blockquote><p>对那些经常声称知道未来的CEO持怀疑态度——如果他们持续达到宣布的目标，我们变得完全难以置信。</p></blockquote><blockquote><p>要成为赢家，就与赢家共事。</p></blockquote><blockquote><p>查理和我今天表现出的对股票的厌恶远非天生。我们喜欢拥有普通股——如果能以有吸引力的价格购买的话。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2002年伯克希尔大幅反弹，净值增长61亿美元，超额收益达32.1个百分点，远超标普500。这一年巴菲特将矛头对准了金融衍生品和公司治理乱象，发出了关于衍生品风险的严厉警告，同时对公司CEO薪酬膨胀、期权操纵利润等行为进行了尖锐批评。通用再保险在经历9·11冲击后逐步恢复承保纪律。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2002年-翻译-·-01-letters-2002年-核心总结-·-01-letters-2002年-思维导图" tabindex="-1"><a href="/01_letters/2002年/翻译.html">01_letters/2002年/翻译</a> · <a href="/01_letters/2002年/核心总结.html">01_letters/2002年/核心总结</a> · <a href="/01_letters/2002年/思维导图.html">01_letters/2002年/思维导图</a> <a class="header-anchor" href="#_01-letters-2002年-翻译-·-01-letters-2002年-核心总结-·-01-letters-2002年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2002年/翻译]] · [[→ 核心总结|01_letters/2002年/核心总结]] · [[→ 思维导图|01_letters/2002年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2002年/翻译.html">/01_letters/2002年/翻译</a></li></ul>',26)])])}const i=t(r,[["render",u]]);export{_ as __pageData,i as default};
